'use strict';
const main=document.querySelector('#main'), modal=document.querySelector('#modal'), content=document.querySelector('#dialog-content');
const product={title:'微单相机与定焦镜头',subtitle:'把校园里的日常，拍成值得留下的瞬间。',price:1680,newPrice:1780};
let refreshed=false, requestId=null, pending=false, lastState='detail';
const money=n=>`<span class="currency">¥</span>${n.toLocaleString('en-US')}`;
const breadcrumb=()=>`<nav class="breadcrumb" aria-label="面包屑"><a href="#list">商品列表</a><span aria-hidden="true">/</span><span>数码电子</span><span aria-hidden="true">/</span><span>商品详情</span></nav>`;
const mini=()=>`<div class="mini-product"><img src="assets/camera.jpg" alt="相机示意照片"><div><strong>${product.title}</strong><small>数码电子 · 图书馆东门交付</small></div></div>`;
function detail(){const price=refreshed?product.newPrice:product.price;main.innerHTML=`${breadcrumb()}<section class="product-grid"><div><div class="photo"><img src="assets/camera.jpg" alt="深色桌面上的微单相机和镜头，商品示意照片"><span>留住校园里的每一个好天气</span><span class="photo-label">商品示意图</span></div><div class="photo-caption"><span>01 / 商品展示</span><span>图片仅用于原型演示</span></div></div><div><div class="eyebrow"><span>数码电子 / 摄影器材</span><span class="status">已发布 · 可预约</span></div><h1>${product.title}</h1><p class="lead">${product.subtitle}</p><div class="price-line"><span class="price">${money(price)}</span><small>线下交易价格</small></div><dl class="meta"><div><dt>交付地点</dt><dd>仙林校区 · 图书馆东门</dd></div><div><dt>商品情况</dt><dd>正常使用，有轻微使用痕迹</dd></div></dl><div class="seller"><span class="avatar">陈</span><div><strong>陈同学</strong><small>发布于 11 月 9 日</small></div><span class="privacy">预约后按权限查看<br>交易联系方式</span></div><button class="btn primary wide" data-action="reserve">预约 <span aria-hidden="true">↗</span></button><p class="under-button">预约不扣款 · 卖家确认后自行约定线下交付</p></div></section><section class="description"><div><h2>关于这件闲置</h2><p>平时用来记录校园生活，现在想把它交给下一个喜欢摄影的人。<br>机身和镜头可正常使用，附电池、充电器及相机背带。<br>欢迎当面检查，具体交付时间在卖家确认后双方协商。</p></div><div class="delivery-note"><strong>预约之后，会发生什么？</strong>卖家需在预约创建后 24 小时内确认。确认前，你可以取消预约；超时未确认将自动释放商品。付款与验货均在线下进行。</div></section>`;}
function unavailable(){main.innerHTML=`<nav class="breadcrumb"><a href="#list">商品列表</a><span>/</span><span>预约结果</span></nav><section class="unavailable"><div class="empty-symbol" aria-hidden="true">−</div><span class="modal-overline">预约未成功</span><h1>慢了一步，商品已被预约</h1><p>另一位买家已预约这件商品，目前无法再次预约。你可以返回列表，看看其他正在出售的闲置。</p><div class="status-line">商品当前状态：<strong>已预约</strong>　·　你的本次提交未创建预约</div><button class="btn primary" data-action="list">返回商品列表 <span aria-hidden="true">→</span></button><p class="footnote">本次没有产生交易，也不会扣款。</p></section>`;}
function list(){main.innerHTML=`<nav class="breadcrumb"><a href="#detail">首页</a><span>/</span><span>商品列表</span></nav><div class="list-heading"><span class="modal-overline">校园里的闲置，值得再用一次</span><h1>发现身边的好物</h1><p>模拟列表 · 当前展示可预约商品</p></div><article class="list-card"><img src="assets/camera.jpg" alt="另一件相机商品的示意照片"><div><span class="status">已发布</span><h2>另一件校园摄影器材</h2><p>模拟商品 · 仙林校区 · 线下交付</p><div class="price">${money(1680)}</div><button class="btn secondary" data-action="reset">进入详情演示 →</button></div></article>`;}
function openDialog(type){const isPrice=type==='price';if(!requestId)requestId=crypto.randomUUID?crypto.randomUUID():String(Date.now());content.innerHTML=`<div class="modal-inner"><div class="modal-top"><span class="modal-overline">${isPrice?'商品信息已更新':'确认你的预约'}</span><button class="close" data-action="cancel" aria-label="关闭弹窗">×</button></div>${isPrice?'<div class="warning-icon" aria-hidden="true">↗</div>':''}<h2 class="modal-title" id="modal-title">${isPrice?'价格有变化，请重新确认':'喜欢的话，先预约下来'}</h2><p class="modal-copy">${isPrice?'你刚才确认的价格已失效。本次未创建预约，也不会自动按新价格提交。':'请核对商品和本次确认的价格，提交后等待卖家确认。'}</p>${mini()}${isPrice?`<div class="price-comparison"><div><small>刚才确认的价格</small><del>¥1,680</del></div><span class="arrow" aria-hidden="true">→</span><div><small>当前价格</small><strong>¥1,780</strong></div></div><p class="price-note">请先查看并确认最新价格。继续后会打开新的预约确认窗口，你可以再次决定是否提交。</p>`:`<div class="summary-row"><span>本次确认价格</span><span class="price">${money(refreshed?product.newPrice:product.price)}</span></div><div class="summary-row"><span>交易方式</span><strong>当面验货 · 线下交付</strong></div><div class="notice">预约不扣款。卖家在 24 小时内确认后，你们可查看本次交易的联系方式并自行约定交付。</div>`}<div class="modal-actions"><button class="btn secondary" data-action="cancel">${isPrice?'暂不预约':'取消'}</button><button class="btn primary" data-action="${isPrice?'reconfirm':'submit'}">${isPrice?'按现价重新确认':'确认预约'}</button></div><p class="fineprint">${isPrice?'重新确认前，不会占用这件商品。':'确认前可取消，卖家确认后须按终止流程处理。'}</p></div>`;modal.showModal();}
function render(){if(modal.open)modal.close();const hashState=location.hash.slice(1);const state=hashState.startsWith('figmacapture=')?(new URLSearchParams(location.search).get('view')||'detail'):(hashState||'detail');lastState=state;pending=false;document.querySelectorAll('[data-view]').forEach(a=>{if(a.dataset.view===state)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(state==='unavailable')unavailable();else if(state==='list')list();else{detail();if(state==='confirm'||state==='price')openDialog(state);}document.title=({detail:'商品详情',confirm:'预约确认',price:'价格变更',unavailable:'已被他人预约',list:'商品列表'}[state]||'商品详情')+' · 校园集';}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='reserve'){requestId=null;go('confirm');}if(action==='cancel'){requestId=null;go('detail');}if(action==='reconfirm'){refreshed=true;requestId=null;go('confirm');}if(action==='list')go('list');if(action==='reset'){refreshed=false;requestId=null;go('detail');}if(action==='submit'&&!pending){pending=true;button.disabled=true;button.textContent='正在提交…';const scenario=document.querySelector('#scenario').value;setTimeout(()=>{pending=false;if(scenario==='price'&&!refreshed){go('price');return;}if(scenario==='unavailable'){go('unavailable');return;}modal.close();detail();const reserve=main.querySelector('[data-action="reserve"]');reserve.disabled=true;reserve.textContent='已预约 · 待卖家确认';main.querySelector('.status').textContent='已预约';main.querySelector('.under-button').textContent='预约成功，等待卖家在 24 小时内确认。';const toast=document.querySelector('#toast');toast.textContent='模拟预约成功 · 当前状态：待卖家确认';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3500);},450);}});
modal.addEventListener('cancel',e=>{e.preventDefault();requestId=null;go('detail');});
window.addEventListener('hashchange',render);if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');render();
